Infrastructure as Code (IaC) tools like Terraform manage cloud network resources by allowing developers to define and provision these resources using declarative configuration files. In Terraform, network resources such as Virtual Private Clouds (VPCs), subnets, route tables, and security groups are defined in a JSON or HCL (HashiCorp Configuration Language) format, which represents the desired state of these resources. Terraform then uses this configuration to interact with the cloud provider’s API, creating, modifying, or deleting resources accordingly.

Here is an example configuration that illustrates how Terraform might define network resources in AWS:

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "subnet-a"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "main-route-table"
  }
}

resource "aws_security_group" "allow_http" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-http"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-gateway"
  }
}
```

