        "PBS": "20000bytes"
      },
      "marking": {
        "green": {
          "condition": "within CIR and CBS",
          "action": "mark packet as Green"
        },
        "yellow": {
          "condition": "exceeding CBS but within PIR and PBS",
          "action": "mark packet as Yellow"
        },
        "red": {
          "condition": "exceeding PIR or PBS",
